begin;
create function pg_temp.expect(value boolean,description text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'FAIL: %',description;end if;end$$;
create function pg_temp.rejects(statement text) returns boolean language plpgsql as $$begin execute statement;return false;exception when others then return true;end$$;
grant execute on function pg_temp.expect(boolean,text),pg_temp.rejects(text) to authenticated,service_role;
set local session_replication_role=replica;
insert into auth.users(id,aud,role,email,created_at,updated_at) values('f8510000-0000-4000-8000-000000000001','authenticated','authenticated','push@example.invalid',now(),now());
insert into public.profiles(auth_id,email,user_id,role,profile_complete) values('f8510000-0000-4000-8000-000000000001','push@example.invalid','push-contract','user',true);
insert into auth.sessions(id,user_id,created_at,updated_at) values('f8510000-1000-4000-8000-000000000001','f8510000-0000-4000-8000-000000000001',now(),now());
insert into public.user_sessions(id,user_id,auth_id,auth_session_id,device_id,device,is_active,trust_status) values('f8510000-2000-4000-8000-000000000001','push-contract','f8510000-0000-4000-8000-000000000001','f8510000-1000-4000-8000-000000000001','push-contract-device','Android',true,'pending');
set local session_replication_role=origin;
select pg_temp.expect(not has_table_privilege('authenticated','public.native_push_devices','select'),'tokens cannot be read by clients');
select pg_temp.expect(not has_table_privilege('anon','public.native_push_jobs','insert'),'anonymous cannot enqueue');
select pg_temp.expect(not has_function_privilege('authenticated','public.claim_native_push_jobs(integer)','execute'),'client cannot dispatch');
select set_config('request.jwt.claims','{"sub":"f8510000-0000-4000-8000-000000000001","role":"authenticated","session_id":"f8510000-1000-4000-8000-000000000001"}',true);
set local role authenticated;
select pg_temp.expect(pg_temp.rejects($$select public.my_native_push_device('push-contract-device','android','enable',repeat('a',80),'push-contract')$$),'pending device denied');
reset role;
update public.user_sessions set trust_status='trusted' where user_id='push-contract';
set local role authenticated;
select pg_temp.expect(pg_temp.rejects($$select public.my_native_push_device('push-contract-device','android','enable',repeat('a',80),'another-account')$$),'cross-account switch denied');
select pg_temp.expect(public.my_native_push_device('push-contract-device','android','enable',repeat('a',80),'push-contract')->>'enabled'='true','confirmed registration receipt');
select pg_temp.expect(public.my_native_push_device('push-contract-device','android','status',null,'push-contract')->>'enabled'='true','status persisted');
reset role;
insert into public.activity_events(activity_event_id,event_key,event_type,subject_type,subject_id,title,route,occurred_at) values('f8510000-3000-4000-8000-000000000001','push-contract-event','saved_search_match','listing','test','Private title never sent','activity',now());
insert into public.activity_event_audiences(activity_event_id,recipient_user_id,workspace) values('f8510000-3000-4000-8000-000000000001','push-contract','personal');
select pg_temp.expect((select count(*)=1 from public.native_push_jobs where user_id='push-contract'),'one durable job');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
create temp table claimed as select * from public.claim_native_push_jobs(50);
select pg_temp.expect((select count(*)=1 from claimed where user_id='push-contract'),'eligible delivery claimed');
select pg_temp.expect((select count(*)=0 from public.claim_native_push_jobs(50) where user_id='push-contract'),'active lease prevents concurrent claim');
select pg_temp.expect(not public.finish_native_push_job((select job_id from claimed where user_id='push-contract'),gen_random_uuid(),'sent','fake',null),'wrong lease cannot complete');
select pg_temp.expect(pg_temp.rejects($$select public.finish_native_push_job(job_id,lease_id,'sent',null,null) from claimed where user_id='push-contract'$$),'missing provider receipt denied');
select pg_temp.expect((select public.finish_native_push_job(job_id,lease_id,'retry',null,'provider_503') from claimed where user_id='push-contract'),'temporary delivery failure acknowledged');
reset role;
select pg_temp.expect((select status='queued' and attempts=1 and available_at>now() from public.native_push_jobs where user_id='push-contract'),'retry delayed and bounded');
select set_config('request.jwt.claims','{"sub":"f8510000-0000-4000-8000-000000000001","role":"authenticated","session_id":"f8510000-1000-4000-8000-000000000001"}',true);
set local role authenticated;
select pg_temp.expect(public.my_native_push_device('push-contract-device','android','disable',null,'push-contract')->>'enabled'='false','off persisted');
reset role;
select pg_temp.expect((select bool_and(status='cancelled') from public.native_push_jobs where user_id='push-contract'),'off cancels queued delivery');
select set_config('request.jwt.claims','{"sub":"f8510000-0000-4000-8000-000000000001","role":"authenticated","session_id":"f8510000-1000-4000-8000-000000000001"}',true);
select public.my_native_push_device('push-contract-device','android','enable',repeat('b',80),'push-contract');
update public.user_sessions set is_active=false where user_id='push-contract';
select pg_temp.expect((select not enabled from public.native_push_devices where user_id='push-contract'),'logout disables device');
select pg_temp.expect(pg_temp.rejects($$select public.my_native_push_device('push-contract-device','android','enable',repeat('c',80),'push-contract')$$),'revoked bearer cannot reenable');
rollback;
